mapper.select:
SELECT n.template_no ,n.notice_type ,FIND_CODENAME(n.notice_type) AS notice_type_name ,n.notice_title ,n.notice_content ,c.class_id
FROM notice_template n join class c ON(n.member_id = c.member_id)
WHERE n.template_no = #{templateNo}

mapper.insert:

	SELECT NVL(MAX(template_no),0) + 1
	FROM notice_template

INSERT INTO notice_template(
		template_no

			,member_id

		,notice_type

			,notice_title

		,notice_content
	)
VALUES (
		#{templateNo}

			,#{memberId}

		,#{noticeType}

			,#{noticeTitle}

		,#{noticeContent}
	)

mapper.update:
UPDATE notice_template


			notice_title = #{noticeTitle},


			notice_content = #{noticeContent}


WHERE template_no = #{templateNo}
